const crypto = require('crypto');
const rows = $input.all();
const row = rows.length && rows[0].json && rows[0].json['Employee Code'] ? rows[0].json : null;
const input = $('When Executed by Another Workflow').first().json;
const employeeCode = (input.employee_code || '').toString().trim().toUpperCase();
const rawPin = (input.pin || '').toString().trim();
const sessionId = input.session_id || '';
const settings = input.settings || {};
const pinLength = Number(settings.PIN_LENGTH || 6);
const maxAttempts = Number(settings.PIN_MAX_ATTEMPTS || 3);
const lockoutMin = Number(settings.PIN_LOCKOUT_MIN || 15);

if (!row) {
  return [{ json: { ok: false, code: 'UNKNOWN_EMPLOYEE_CODE', employee_code: employeeCode, session_id: sessionId } }];
}

const storedHash = (row['PIN Hash'] || '').toString().trim();
const failedAttempts = Number(row['Failed Attempts'] || 0);
const lockedUntilStr = (row['Locked Until'] || '').toString().trim();

// 1. Lock check
if (lockedUntilStr) {
  const lockedUntil = new Date(lockedUntilStr);
  if (!isNaN(lockedUntil.getTime()) && lockedUntil > new Date()) {
    return [{ json: { ok: false, code: 'PIN_LOCKED', locked_until: lockedUntilStr, employee_code: employeeCode, session_id: sessionId } }];
  }
}

// 2. PIN missing check
if (!storedHash) {
  return [{ json: { ok: false, code: 'PIN_NOT_SET', employee_code: employeeCode, session_id: sessionId } }];
}

// 3. Format check
if (!/^\d+$/.test(rawPin) || rawPin.length !== pinLength) {
  return [{ json: { ok: false, code: 'INVALID_PIN_FORMAT', attempts_left: maxAttempts - failedAttempts, employee_code: employeeCode, session_id: sessionId } }];
}

// 4. Hash and compare
const pepper = process.env.APP_PIN_PEPPER || $vars.WORKLOG_PEPPER || 'default_worklog_pepper_secret_hex';
const computedHash = crypto.createHmac('sha256', pepper).update(rawPin).digest('hex');

let isMatch = false;
try {
  const b1 = Buffer.from(computedHash, 'hex');
  const b2 = Buffer.from(storedHash, 'hex');
  if (b1.length === b2.length) {
    isMatch = crypto.timingSafeEqual(b1, b2);
  }
} catch (e) {
  isMatch = false;
}

const nowIso = new Date().toISOString();

if (isMatch) {
  return [{
    json: {
      ok: true,
      action: 'CLEAR_FAILED',
      employee_code: employeeCode,
      verified_at: nowIso,
      session_id: sessionId
    }
  }];
} else {
  const newFailed = failedAttempts + 1;
  if (newFailed >= maxAttempts) {
    const lockedUntilDate = new Date(Date.now() + lockoutMin * 60 * 1000).toISOString();
    return [{
      json: {
        ok: false,
        action: 'LOCK_ACCOUNT',
        code: 'PIN_LOCKED',
        employee_code: employeeCode,
        failed_attempts: newFailed,
        locked_until: lockedUntilDate,
        session_id: sessionId
      }
    }];
  } else {
    return [{
      json: {
        ok: false,
        action: 'INCREMENT_FAILED',
        code: 'PIN_MISMATCH',
        employee_code: employeeCode,
        failed_attempts: newFailed,
        attempts_left: maxAttempts - newFailed,
        session_id: sessionId
      }
    }];
  }
}

const v = $('Verify and Compare PIN').first().json;
const res = { ok: v.ok };
if (v.code) res.code = v.code;
if (v.attempts_left != null) res.attempts_left = v.attempts_left;
if (v.locked_until) res.locked_until = v.locked_until;
if (v.verified_at) res.verified_at = v.verified_at;
return [{ json: res }];
